List<int> fn0(String a, int b) {
  final List<int> result = <int>[];

  int count = 0;
  for (int i = 0; i <= a.length; i++) {
    final bool atDelimiter = i >= a.length || a[i] == ' ';

    if (!atDelimiter) {
      count++;
      continue;
    }

    if (count > 0) {
      final List<int> digits = <int>[];
      int value = count;

      while (value > 0) {
        digits.add(value % b);
        value ~/= b;
      }

      result.addAll(digits.reversed);
      result.add(-1);
    }

    count = 0;
  }

  if (result.isNotEmpty) {
    result.length = result.length - 1;
  }

  return result;
}

